            byType[types[i]].add(item);
            all.add(item);
        }

        int c = fs.nextInt();
        long total = 0;

        for (int i = 0; i < c; i++) {
            int desiredType = fs.nextInt();

            if (desiredType == 0) {
                while (!all.isEmpty() && !active[all.peek().id]) {
                    all.poll();
                }
                if (!all.isEmpty()) {
                    Item item = all.poll();
                    active[item.id] = false;
                    total += item.price;
                }
            } else {
                PriorityQueue<Item> queue = byType[desiredType];
                if (queue == null) continue;

                while (!queue.isEmpty() && !active[queue.peek().id]) {
                    queue.poll();
                }
                if (!queue.isEmpty()) {
                    Item item = queue.poll();
                    active[item.id] = false;
                    total += item.price;
                }
            }
        }

        System.out.println(total);
    }
}
